import{_ as a,o,c as t,a2 as n}from"./chunks/framework.BWuWLRhz.js";const m=JSON.parse('{"title":"Protocolo URI (lertaro://)","description":"","frontmatter":{},"headers":[],"relativePath":"es-ES/user-guide/uri-protocol.md","filePath":"es-ES/user-guide/uri-protocol.md","lastUpdated":1786513079000}'),r={name:"es-ES/user-guide/uri-protocol.md"};function c(d,e,s,i,l,u){return o(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="protocolo-uri-lertaro" tabindex="-1">Protocolo URI (lertaro://) <a class="header-anchor" href="#protocolo-uri-lertaro" aria-label="Permalink to &quot;Protocolo URI (lertaro://)&quot;">​</a></h1><p>Lertaro se registra a sí mismo como el gestor de un enlace <code>lertaro://</code> — sin ningún paso de instalación aparte, se configura automáticamente la primera vez que se ejecuta la aplicación. Esto permite que cualquier cosa capaz de abrir un enlace (un navegador, un acceso directo, otra aplicación, un script) salte directamente a una parte concreta de Lertaro, en lugar de ser accesible solo mediante un atajo de teclado.</p><p>Si Lertaro aún no está en ejecución, abrir un enlace <code>lertaro://</code> lo inicia y luego sigue el enlace. Si ya está en ejecución, la instancia en ejecución gestiona el enlace directamente — nunca inicia una segunda copia.</p><h2 id="rutas" tabindex="-1">Rutas <a class="header-anchor" href="#rutas" aria-label="Permalink to &quot;Rutas&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Enlace</th><th>Qué hace</th></tr></thead><tbody><tr><td><code>lertaro://</code></td><td>Activa la ventana de búsqueda rápida — lo mismo que invocarla con su atajo.</td></tr><tr><td><code>lertaro://search/[keyword]</code></td><td>Activa la ventana de búsqueda rápida con <code>[keyword]</code> ya escrito.</td></tr><tr><td><code>lertaro://fullsearch/[keyword]</code></td><td>Abre la ventana de búsqueda completa con <code>[keyword]</code> ya escrito.</td></tr><tr><td><code>lertaro://settings/page/[section]</code></td><td>Abre Configuración en una sección concreta de nivel superior.</td></tr><tr><td><code>lertaro://settings/entry/[index]</code></td><td>Abre Configuración y salta directamente a un ajuste concreto, resaltado.</td></tr><tr><td><code>lertaro://localsend</code></td><td>Abre una ventana de envío de LocalSend vacía.</td></tr><tr><td><code>lertaro://localsend/items[/encoded-item...]</code></td><td>Cambia al modo de archivos/carpetas y, opcionalmente, añade un segmento de ruta codificado por elemento.</td></tr><tr><td><code>lertaro://localsend/text[/encoded-text]</code></td><td>Cambia al modo de texto y, opcionalmente, rellena el texto codificado.</td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lertaro://search/report</span></span>
<span class="line"><span>lertaro://settings/page/Appearance</span></span></code></pre></div><p>El primero activa la ventana de búsqueda rápida ya filtrada a &quot;report&quot;; el segundo abre Configuración directamente en la página Apariencia.</p><p><code>[section]</code> coincide con una de las entradas de nivel superior de la barra lateral: <code>Service</code>, <code>Index</code>, <code>General</code>, <code>Appearance</code>, <code>Hotkeys</code>, <code>Plugins</code>, <code>Favorites</code>, <code>History</code>, <code>QuickPanel</code>, <code>About</code> — sin distinguir mayúsculas de minúsculas.</p><p><code>[index]</code> no está pensado para escribirse a mano — es un número que la propia <a href="./instant-answers.html">Búsqueda de configuración</a> genera para el ajuste que hayas elegido, de modo que seleccionar uno de sus resultados te devuelve directamente a esa fila exacta. No es estable entre reinicios, así que no cuentes con que un número concreto se mantenga igual.</p><h2 id="enlaces-de-localsend" tabindex="-1">Enlaces de LocalSend <a class="header-anchor" href="#enlaces-de-localsend" aria-label="Permalink to &quot;Enlaces de LocalSend&quot;">​</a></h2><p>Cada ruta de archivo/carpeta o valor de texto debe codificarse como un segmento de ruta URL completo. Para añadir varios elementos, agrega un segmento codificado por elemento; todas las rutas deben ser absolutas y existir previamente. Por ejemplo:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lertaro://localsend/items/C%3A%5CUsers%5Ctestuser%5CDesktop%5Ca.txt/D%3A%5CShared</span></span>
<span class="line"><span>lertaro://localsend/text/Hello%20world</span></span></code></pre></div><p><code>lertaro://localsend/items</code> abre la página de recopilación en modo de archivos/carpetas, mientras que <code>lertaro://localsend/text</code> la abre en modo de texto. Un enlace con contenido avanza a la selección de dispositivos, pero nunca selecciona un dispositivo ni inicia una transferencia automáticamente. Si ya hay una ventana de envío abierta, el enlace no hace nada ni cambia su contenido o estado actual. Si LocalSend está desactivado, Lertaro abre su página de configuración de LocalSend. El contenido no válido o demasiado largo hace que se ignore toda la solicitud.</p><h2 id="enlaces-no-reconocidos" tabindex="-1">Enlaces no reconocidos <a class="header-anchor" href="#enlaces-no-reconocidos" aria-label="Permalink to &quot;Enlaces no reconocidos&quot;">​</a></h2><p>Cualquier cosa que no coincida con una ruta conocida — una errata, una sección no admitida, basura después de <code>lertaro://</code> — se ignora en silencio. Dado que cualquier sitio web o aplicación puede invocar este protocolo sin pedirte permiso antes, un enlace erróneo o inesperado nunca debería hacer nada sorprendente; se registra para tu propia solución de problemas, pero no ocurre nada más.</p>`,15)])])}const h=a(r,[["render",c]]);export{m as __pageData,h as default};
